// Dedupe and the auto-generated mirror trace (qvis `ensureMoreThanOneTrace`, SequenceDiagramD3Renderer.ts:405-569;
// parity/sequence-diagram.md §3.4, SQ6, SQ7, SQ33, §9.6).
//
// A sequence diagram needs two sides. When only one trace is selected, a mirror of it is generated: a clone (sharing
// the untouched raw events) in which packet_sent and packet_received are swapped and every other event is renamed to
// `<namespace>:ignoreseq` (laid out, never drawn). The clone is registered in the original's group (it shows up in
// every selector, SQ32 PRESERVE) and reused on later renders.

import type { QlogConnection } from "@/model/QlogConnection";
import type { QlogEvent } from "@/model/QlogEvent";
import SequenceDiagramConfig, { type SequenceDiagramConnection } from "./data/SequenceDiagramConfig";
import { absoluteTime, getGeneratedSibling, setGeneratedSiblings } from "./timeModel";

/** Type given to every non-packet event of a generated trace (qvis `ignoreEventName`). */
export const IGNORE_EVENT_TYPE = "ignoreseq";

export const GENERATED_PREFIX = "Simulated, autogenerated trace : ";
export const GENERATED_VANTAGE_NAME = "GENERATED";
export const UNKNOWN_VANTAGE_NAME_PREFIX = "vantage point type was unknown, pretending it's ";

/** True for the transport-level packet_sent of `conn` (`quic:packet_sent`, `tcp:packet_sent` for converter traces). */
export function isPacketSent(ev: QlogEvent, conn: QlogConnection = ev.conn): boolean {
    return ev.type === "packet_sent" && ev.namespace === conn.transportNamespace;
}

/** True for the transport-level packet_received of `conn`. */
export function isPacketReceived(ev: QlogEvent, conn: QlogConnection = ev.conn): boolean {
    return ev.type === "packet_received" && ev.namespace === conn.transportNamespace;
}

function header(ev: QlogEvent): Record<string, any> | undefined {
    const h = ev.data ? ev.data.header : undefined;
    return typeof h === "object" && h !== null ? h : undefined;
}

function firstInitialZero(events: readonly QlogEvent[]): QlogEvent | undefined {
    for (const ev of events) {
        const h = header(ev);
        if (h && h.packet_type === "initial" && "" + h.packet_number === "0") return ev;
    }
    return undefined;
}

/**
 * Vantage point guess for a trace whose type is neither client nor server (`:485-540`). The client sends the first
 * Initial (PN 0) before it receives one; default "server". Compares real event times (data-model Q1 FIX: qvis's cursor
 * parser made this always "server").
 */
export function guessPerspective(original: QlogConnection): "client" | "server" {
    const ns = original.transportNamespace;
    const firstInitialSent = firstInitialZero(original.lookup(ns, "packet_sent"));
    const firstInitialReceived = firstInitialZero(original.lookup(ns, "packet_received"));
    let guessed: "client" | "server" = "server"; // server is a logical default, probably more of those available
    if (firstInitialSent && firstInitialReceived) {
        if (absoluteTime(firstInitialSent) < absoluteTime(firstInitialReceived)) guessed = "client";
    }
    return guessed;
}

/**
 * Creates the mirror trace of `original` (registered in its group) and links both as generated siblings.
 * Returns the mirror and whether it belongs to the left of the original.
 */
export function createMirror(original: QlogConnection): { mirror: QlogConnection; placeLeft: boolean } {
    const ns = original.transportNamespace;
    const newTrace = original.clone((ev) => {
        if (ev.namespace === ns && ev.type === "packet_sent")
            return { namespace: ev.namespace, type: "packet_received" };
        if (ev.namespace === ns && ev.type === "packet_received")
            return { namespace: ev.namespace, type: "packet_sent" };
        // we cannot observe anything from the "other" side besides what we received, so dismantle all of those events
        return { namespace: ev.namespace, type: IGNORE_EVENT_TYPE };
    });
    newTrace.wasAutoGenerated = true;

    const ovp = original.vantagePoint;
    const vp = { ...newTrace.vantagePoint, name: GENERATED_VANTAGE_NAME };
    let placeLeft: boolean;

    // we have a single trace, we need to copy it so we can simulate client + server
    if (ovp.type === "server" || ovp.flow === "server") {
        vp.type = "client";
        vp.flow = "unknown";
        placeLeft = true;
    } else if (ovp.type === "client" || ovp.flow === "client") {
        vp.type = "server";
        vp.flow = "unknown";
        placeLeft = false;
    } else {
        // the vantagepoint is unknown... it's either client or server: guess from the Initials
        const guessed = guessPerspective(original);
        original.setVantagePoint({ ...ovp, name: UNKNOWN_VANTAGE_NAME_PREFIX + guessed });

        vp.type = guessed === "client" ? "server" : "client";
        vp.name = UNKNOWN_VANTAGE_NAME_PREFIX + vp.type;
        vp.flow = "unknown";
        placeLeft = vp.type !== "server";
    }

    newTrace.setTitle(GENERATED_PREFIX + original.title);
    newTrace.setDescription(GENERATED_PREFIX + original.description);
    newTrace.setVantagePoint(vp);

    setGeneratedSiblings(original, newTrace);
    return { mirror: newTrace, placeLeft };
}

/** SQ6 FIX: the same connection selected twice is kept once (the first wrapper). Returns a new array. */
export function dedupeTraces(input: readonly SequenceDiagramConnection[]): SequenceDiagramConnection[] {
    const seen = new Set<QlogConnection>();
    const traces: SequenceDiagramConnection[] = [];
    for (const t of input) {
        if (seen.has(t.connection)) continue;
        seen.add(t.connection);
        traces.push(t);
    }
    return traces;
}

/**
 * Dedupe (SQ6 FIX: by connection identity, keeping the first) and, when a single trace remains, add its mirror: the
 * remembered generated sibling (SQ7 FIX: placed by perspective) or a new one. Returns the traces to render: the input
 * wrappers are kept, the mirror gets a new wrapper. The input array is not modified.
 */
export function ensureMoreThanOneTrace(input: readonly SequenceDiagramConnection[]): SequenceDiagramConnection[] {
    const traces = dedupeTraces(input);
    if (traces.length !== 1) return traces;

    const trace = traces[0].connection;

    // we've already generated a trace for this one, so re-use it
    const sibling = getGeneratedSibling(trace);
    if (sibling !== undefined) {
        const sp = sibling.getVantagePointPerspective();
        const siblingLeft = sp === "client" || (sp === "unknown" && trace.getVantagePointPerspective() === "server");
        const wrapped = SequenceDiagramConfig.createConnectionWithTimeoffset(sibling);
        if (siblingLeft) traces.unshift(wrapped);
        else traces.push(wrapped);
        return traces;
    }

    // we cannot just visualize a single trace on a sequence diagram...
    // so we copy the trace and pretend like the copy is one from the other side
    const { mirror, placeLeft } = createMirror(trace);
    const wrapped = SequenceDiagramConfig.createConnectionWithTimeoffset(mirror);
    if (placeLeft) traces.unshift(wrapped);
    else traces.push(wrapped);
    return traces;
}
